#!/usr/bin/env node
/**
 * S4-02 UserData Snapshot Comparator for Windows Upgrade & Uninstall QA.
 * Compares two JSON snapshots generated by scripts/windows-qa-preflight.ps1
 * (-Mode snapshot-before vs -Mode snapshot-after) and produces a verifiable
 * preservation verdict without external dependencies.
 */
'use strict';

const fs = require('fs');
const path = require('path');

/** Critical user data assets that must NEVER vanish across upgrade or default uninstall. */
const CRITICAL_PRESERVED_ASSETS = [
  'arc.db',
  'secrets.json',
  'tts-policy.json',
  'config/ai-providers.json',
  'macros',
  'models',
  'tts_dicts',
  'backups'
];

/**
 * Compares before/after userData snapshot payloads.
 * @param {object} beforeSnap
 * @param {object} afterSnap
 * @param {{ scenario?: 'upgrade' | 'uninstall' }} [options]
 */
function compareQaSnapshots(beforeSnap, afterSnap, options = {}) {
  const scenario = options.scenario === 'uninstall' ? 'uninstall' : 'upgrade';
  const beforeMap = new Map();
  const afterMap = new Map();

  for (const entry of Array.isArray(beforeSnap?.userDataSnapshot) ? beforeSnap.userDataSnapshot : []) {
    if (entry && typeof entry.path === 'string') beforeMap.set(entry.path, entry);
  }
  for (const entry of Array.isArray(afterSnap?.userDataSnapshot) ? afterSnap.userDataSnapshot : []) {
    if (entry && typeof entry.path === 'string') afterMap.set(entry.path, entry);
  }

  const allPaths = Array.from(new Set([...beforeMap.keys(), ...afterMap.keys()])).sort();
  const assetDiffs = [];
  const failures = [];
  const warnings = [];

  for (const relPath of allPaths) {
    const before = beforeMap.get(relPath) || { path: relPath, exists: false, type: 'missing', sizeBytes: 0, sha256: null };
    const after = afterMap.get(relPath) || { path: relPath, exists: false, type: 'missing', sizeBytes: 0, sha256: null };
    const isCritical = CRITICAL_PRESERVED_ASSETS.includes(relPath);

    let status = 'unchanged';
    if (!before.exists && !after.exists) {
      status = 'absent_both';
    } else if (before.exists && !after.exists) {
      status = 'deleted';
      if (isCritical) {
        failures.push(`Critical user asset deleted during ${scenario}: ${relPath}`);
      } else {
        warnings.push(`Non-critical asset removed during ${scenario}: ${relPath}`);
      }
    } else if (!before.exists && after.exists) {
      status = 'created';
    } else if (before.type === 'file' && after.type === 'file') {
      if (before.sizeBytes > 0 && after.sizeBytes === 0 && isCritical) {
        status = 'truncated_to_zero';
        failures.push(`Critical user file truncated to 0 bytes during ${scenario}: ${relPath}`);
      } else if (before.sha256 && after.sha256 && before.sha256 !== after.sha256) {
        status = 'modified';
        if (scenario === 'uninstall' && isCritical) {
          failures.push(`Critical user file unexpectedly modified during uninstall: ${relPath}`);
        }
      } else {
        status = 'unchanged';
      }
    } else if (before.type === 'directory' && after.type === 'directory') {
      const beforeCount = Number(before.fileCount || 0);
      const afterCount = Number(after.fileCount || 0);
      if (beforeCount > 0 && afterCount === 0 && isCritical) {
        status = 'emptied';
        failures.push(`Critical user directory emptied during ${scenario}: ${relPath} (${beforeCount} -> 0 files)`);
      } else if (beforeCount !== afterCount || before.sizeBytes !== after.sizeBytes) {
        status = 'modified';
        if (scenario === 'uninstall' && isCritical && afterCount < beforeCount) {
          failures.push(`Critical user directory lost files during uninstall: ${relPath} (${beforeCount} -> ${afterCount})`);
        }
      } else {
        status = 'unchanged';
      }
    } else {
      status = 'type_changed';
      if (isCritical) {
        failures.push(`Critical user asset changed type (${before.type} -> ${after.type}): ${relPath}`);
      }
    }

    assetDiffs.push({
      path: relPath,
      critical: isCritical,
      status,
      before: {
        exists: Boolean(before.exists),
        type: before.type || 'missing',
        sizeBytes: Number(before.sizeBytes || 0),
        fileCount: before.fileCount !== undefined ? Number(before.fileCount) : undefined,
        sha256: before.sha256 || null
      },
      after: {
        exists: Boolean(after.exists),
        type: after.type || 'missing',
        sizeBytes: Number(after.sizeBytes || 0),
        fileCount: after.fileCount !== undefined ? Number(after.fileCount) : undefined,
        sha256: after.sha256 || null
      }
    });
  }

  if (beforeSnap?.userDataExists && !afterSnap?.userDataExists) {
    failures.push(`Entire userData directory missing after ${scenario}`);
  }

  return {
    schemaVersion: 1,
    comparedAt: new Date().toISOString(),
    scenario,
    verdict: failures.length === 0 ? 'PASS' : 'FAIL',
    beforeCapturedAt: beforeSnap?.capturedAt || null,
    afterCapturedAt: afterSnap?.capturedAt || null,
    failures,
    warnings,
    assetDiffs
  };
}

function runCli(argv = process.argv.slice(2)) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token === '--before' && argv[i + 1]) args.before = argv[++i];
    else if (token === '--after' && argv[i + 1]) args.after = argv[++i];
    else if (token === '--out' && argv[i + 1]) args.out = argv[++i];
    else if (token === '--scenario' && argv[i + 1]) args.scenario = argv[++i];
  }

  if (!args.before || !args.after) {
    console.error('Usage: node scripts/compare-qa-snapshots.cjs --before <file.json> --after <file.json> [--scenario upgrade|uninstall] [--out <report.json>]');
    process.exit(2);
  }

  const beforeSnap = JSON.parse(fs.readFileSync(path.resolve(args.before), 'utf8'));
  const afterSnap = JSON.parse(fs.readFileSync(path.resolve(args.after), 'utf8'));
  const report = compareQaSnapshots(beforeSnap, afterSnap, { scenario: args.scenario });

  if (args.out) {
    const outPath = path.resolve(args.out);
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, JSON.stringify(report, null, 2) + '\n', 'utf8');
    console.log(`[QA Snapshot Diff] Verdict=${report.verdict}, saved report to ${outPath}`);
  } else {
    console.log(JSON.stringify(report, null, 2));
  }

  if (report.verdict !== 'PASS') {
    for (const f of report.failures) {
      console.error(`  [FAIL] ${f}`);
    }
    process.exit(1);
  }
  process.exit(0);
}

if (require.main === module) {
  runCli();
}

module.exports = {
  CRITICAL_PRESERVED_ASSETS,
  compareQaSnapshots
};
